@workflow.defn
class TaskRun:
    def __init__(self) -> None:
        self.failures = 0          # görev toplamı; hiçbir model veya alt ajan sıfırlayamaz
        self.po_decision: str | None = None

    @workflow.signal
    def po_answered(self, decision: str) -> None:
        self.po_decision = decision

    @workflow.run
    async def run(self, task: TaskInput) -> str:
        policy = task.policy                     # sürümlü policy.yaml, run başında sabit
        spec = await workflow.execute_activity(
            research, task,
            start_to_close_timeout=timedelta(minutes=30),
            retry_policy=INFRA_RETRY,             # 1 + 2 tekrar, 10 / 30 sn
        )
        if spec.ambiguous:
            await workflow.execute_activity(plane_set_status, "WAITING_FOR_PO", ...)
            await workflow.wait_condition(lambda: self.po_decision is not None)

        for behavior in spec.behaviors:
            red = await workflow.execute_activity(write_failing_test, behavior, ...)
            if not red.failed_for_expected_reason:
                return await self.stop("BLOCKED_TEST", red)
            while True:
                if self.failures >= policy.per_task.failed_attempts:
                    return await self.stop("ERROR", behavior)
                result = await workflow.execute_activity(
                    coding_agent, behavior,
                    heartbeat_timeout=timedelta(minutes=2),
                    start_to_close_timeout=timedelta(minutes=policy.per_task.active_minutes),
                )
                gates = await workflow.execute_activity(run_ci_gates, result.sha, ...)  # yapay zekâ yok
                if gates.green:
                    break
                self.failures += 1
        return "READY_FOR_ALPHA"
